contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take an amount to deposit
    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // record balances before
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // perform deposit of `amount` into c
        c.deposit{value: amount}();

        // record balances after deposit
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // call withdrawAll and observe whether it reverts
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // balances after withdraw attempt
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;

        // General rule:
        // 1) deposit increases c.balance by exactly amount and decreases this contract by that amount
        // 2) withdrawAll either succeeds and returns exactly that amount (so this contract net equals beforeThis)
        //    and c.balance decreases accordingly, or it reverts and balances stay as afterDeposit values.
        assert(
            // deposit effect
            afterDepositC == beforeC + amount
            && afterDepositThis == beforeThis - amount
            && (
                // If withdrawAll reverted: balances unchanged from afterDeposit
                (reverted && finalC == afterDepositC && finalThis == afterDepositThis)
                ||
                // If withdrawAll succeeded: this contract should have regained the amount and c decreased by amount
                (!reverted && finalC + amount == afterDepositC && finalThis == afterDepositThis + amount)
            )
        );
    }

    // accept Ether for withdraw callbacks
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function driving the contract
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);
        // Record c's balance before any action
        uint beforeC = address(c).balance;

        // Make a deposit on behalf of this test contract to set credit[msg.sender]
        c.deposit{value: depositAmount}();

        // After deposit, c's balance must have increased by depositAmount
        uint afterDepositC = address(c).balance;

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe c's balance after the withdraw attempt
        uint afterWithdrawC = address(c).balance;

        // If withdraw reverted, c's balance must be unchanged from afterDepositC.
        // If withdraw succeeded, c's balance must have decreased by exactly depositAmount.
        // Also, on success the contract should no longer be able to withdraw that credit again:
        // calling withdrawAll a second time must revert or not change c's balance further.
        bool secondReverted;
        uint midBalance = afterWithdrawC;
        try c.withdrawAll() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        uint finalBalance = address(c).balance;

        assert(
            // after making the deposit, the contract's balance increased by depositAmount
            afterDepositC == beforeC + depositAmount
            && (
                // Case: first withdraw reverted -> no change in c's balance and second withdraw also makes no further decrease
                (reverted && afterWithdrawC == afterDepositC && finalBalance == afterDepositC)
                ||
                // Case: first withdraw succeeded -> c lost exactly depositAmount and subsequent withdraw cannot decrease it further
                (!reverted && afterWithdrawC + depositAmount == afterDepositC && finalBalance == afterWithdrawC)
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function driving c and asserting the invariant
    function run(uint firstDeposit, uint secondDeposit) public payable {
        // We will send Ether to c using the provided deposit amounts. Ensure this contract
        // has enough balance to perform the payments.
        require(address(this).balance >= firstDeposit + secondDeposit);

        // 1) Make an initial deposit of firstDeposit from this test contract to c
        c.deposit{value: firstDeposit}();

        // 2) Make a second deposit of secondDeposit (could be zero)
        c.deposit{value: secondDeposit}();

        // Record c's balance before withdrawAll
        uint beforeCBalance = address(c).balance;

        // Try to call withdrawAll and capture whether it reverted
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the withdrawAll attempt, the caller (this contract) may or may not have
        // received funds. We check the observable effects on c: either its balance is
        // unchanged if withdrawAll reverted, or it decreased by the amount of cleared credit
        // and a subsequent withdrawAll should behave accordingly. To observe the caller's
        // remaining credit we attempt another withdrawAll and see whether it would revert
        // (i.e., whether there is remaining credit to send).

        // Record c balance after first withdraw attempt
        uint afterCBalance = address(c).balance;

        // Attempt a second withdraw and record whether it reverts
        bool revertedSecond;
        try c.withdrawAll() {
            revertedSecond = false;
        } catch {
            revertedSecond = true;
        }

        // General rule asserted:
        // If the first withdrawAll reverted, then c's balance must be unchanged and
        // the second withdrawAll's revert-ness equals the first (no state change happened).
        // Otherwise (first succeeded), c's balance decreased (or stayed the same if cleared credit was zero),
        // and the second withdrawAll must revert (caller credit was cleared to zero).
        assert(
            (reverted && afterCBalance == beforeCBalance && revertedSecond == reverted)
            ||
            (!reverted && afterCBalance <= beforeCBalance && revertedSecond == true)
        );
    }

    // Allow receiving Ether when c sends funds back
    receive() external payable {}
}

