contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function driving c and asserting the invariant
    function run(uint depositAmount) public payable {
        // ensure this test contract has enough balance to deposit
        require(address(this).balance >= depositAmount);

        // record balances before deposit
        uint beforeCTest = address(c).balance;
        uint beforeThis = address(this).balance;

        // make a single deposit of depositAmount from this test contract to c
        c.deposit{value: depositAmount}();

        // record balances after deposit and before withdraw
        uint afterDepositC = address(c).balance;
        uint afterDepositThis = address(this).balance;

        // require that the deposit actually changed balances consistently (safety precondition)
        // This avoids degenerate cases where the environment doesn't transfer Ether.
        require(afterDepositC == beforeCTest + depositAmount);
        require(afterDepositThis == beforeThis - depositAmount);

        // attempt withdrawAll and record whether it reverted
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }

        // record balances after withdraw attempt
        uint finalC = address(c).balance;
        uint finalThis = address(this).balance;

        // General rule: either withdraw reverted leaving c's balance unchanged and this contract balance unchanged,
        // or withdraw succeeded and c's balance decreased by exactly depositAmount and this contract balance increased by exactly depositAmount.
        assert(
            (!withdrew && finalC == afterDepositC && finalThis == afterDepositThis)
            ||
            (withdrew && finalC + depositAmount == afterDepositC && finalThis == afterDepositThis + depositAmount)
        );
    }

    // allow receiving Ether when c sends funds back
    receive() external payable {}
}

