contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: take two deposit amounts and perform deposit(A), deposit(B), then withdrawAll
    function run(uint a, uint b) public payable {
        // ensure this contract has enough Ether to make both deposits
        require(address(this).balance >= a + b);

        // perform two top-level state-changing calls to c
        c.deposit{value: a}();
        c.deposit{value: b}();

        // record c's balance before withdraw, and this contract balance
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        // call withdrawAll and catch if it reverts
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // compute total deposited as observable: should equal beforeC - (initial c balance which was 0 since fresh c),
        // but we avoid assuming initial balance; instead we know delta in this test's view: totalDeposit = a + b
        uint totalDeposit = a + b;

        // After first withdrawAll: either reverted (no balances changed), or succeeded and this contract received exactly totalDeposit
        // And if succeeded, a subsequent withdrawAll must not transfer anything (credit cleared) — we express that by calling it and checking it does not increase this contract balance.

        // perform second withdraw attempt to observe whether any additional Ether is transferred
        uint midThis = address(this).balance;
        bool reverted2;
        try c.withdrawAll() {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint finalThis = address(this).balance;

        // Now assert the general invariant combining cases:
        // If initial credit was zero (totalDeposit == 0) then no balances changed by the first withdraw (either revert or no transfer).
        // Otherwise, if first withdraw reverted then balances unchanged; if first withdraw succeeded then this contract gained exactly totalDeposit and subsequent withdraw gave nothing more.
        assert(
            // Case totalDeposit == 0: no change across calls
            (totalDeposit == 0 && beforeC == afterC && beforeThis == afterThis)
            ||
            // Case totalDeposit > 0:
            (totalDeposit > 0 && (
                // either first withdraw reverted: balances unchanged
                (reverted && beforeC == afterC && beforeThis == afterThis)
                ||
                // or first withdraw succeeded: this contract gained exactly totalDeposit and subsequent withdraw transfer is zero
                (!reverted && afterThis == beforeThis + totalDeposit && afterC + totalDeposit == beforeC && finalThis == afterThis)
            ))
        );
    }

    // allow receiving Ether from c during withdraw
    receive() external payable {}
}
